// カレンダーデータを整形してGeminiに渡しやすい形式にする
const events = $input.all();

if (events.length === 0) {
  return [
    {
      json: {
        eventsText: "今日は予定がありません。1日を自由に使えます。",
        eventCount: 0,
        rawEvents: []
      }
    }
  ];
}

// イベントを時系列で整理
const formattedEvents = events.map(event => {
  const start = event.json.start?.dateTime || event.json.start?.date;
  const end = event.json.end?.dateTime || event.json.end?.date;

  return {
    summary: event.json.summary || '(タイトルなし)',
    start: start,
    end: end,
    location: event.json.location || '',
    description: event.json.description || ''
  };
});

// テキスト形式に変換
const eventsText = formattedEvents.map((e, i) => {
  const startTime = new Date(e.start).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });
  const endTime = new Date(e.end).toLocaleTimeString('ja-JP', { hour: '2-digit', minute: '2-digit' });

  return `${i + 1}. ${e.summary}\n   時間: ${startTime} - ${endTime}\n   場所: ${e.location || 'なし'}`;
}).join('\n\n');

return [
  {
    json: {
      eventsText: eventsText,
      eventCount: formattedEvents.length,
      rawEvents: formattedEvents
    }
  }
];
